  "items": [
    {
      "ref": "E1",
      "kind": "epic",
      "parent_ref": null,
      "title": "Room Search and Booking Management",
      "description": "Enables students and staff to independently search for free study rooms and book one-off slots using their college credentials while preventing double bookings. This delivers a transparent self-service booking experience and eliminates scheduling conflicts.",
      "criteria": [
        {
          "text": "When a user searches for rooms, results reflect available slots by date, time, and capacity.",
          "origin": "source",
          "citations": [
            {
              "block_id": "B8",
              "quote": "- A user can search rooms by date, time and capacity, and book an individual one-off slot."
            }
          ]
        },
        {
          "text": "When a user attempts to book an already occupied room slot, the booking is rejected.",
          "origin": "source",
          "citations": [
            {
              "block_id": "B15",
              "quote": "The booking service will reject an overlapping booking for the same room."
            }
          ]
        }
      ],
      "assumptions": [],
      "open_questions": [],
      "covers": []
    },
    {
      "ref": "S1",
      "kind": "story",
      "parent_ref": "E1",
      "title": "Sign in with college account",
      "description": "As a student or staff member, I want to sign in with my existing college account, so that I can access the room booking service.\n\nUsers need a secure and authenticated way to access the booking platform using existing credentials.",
      "criteria": [
        {
          "text": "When a user accesses the platform, they can sign in using their existing college account credentials.",
          "origin": "source",
          "citations": [
            {
              "block_id": "B8",
              "quote": "- Students and staff sign in with their existing college account."
            }
          ]
        },
        {
          "text": "When authentication succeeds, the user is granted access to the booking features.",
          "origin": "proposed",
          "citations": []
        }
      ],
      "assumptions": [],
      "open_questions": [],
      "covers": [
        "T6"
      ]
    },
    {
      "ref": "S2",
      "kind": "story",
      "parent_ref": "E1",
      "title": "Search and book study rooms",
      "description": "As a student or staff member, I want to search rooms by date, time and capacity, and book an individual one-off slot, so that I can secure a room for study sessions.\n\nUsers need to find available rooms matching their criteria and make single bookings without conflicts.",
      "criteria": [
        {
          "text": "When a user specifies date, time, and capacity, the system displays matching free rooms.",
          "origin": "source",
          "citations": [
            {
              "block_id": "B8",
              "quote": "- A user can search rooms by date, time and capacity, and book an individual one-off slot."
            }
          ]
        },
        {
          "text": "When a user books a room slot, the booking is confirmed.",
          "origin": "source",
          "citations": [
            {
              "block_id": "B8",
              "quote": "and book an individual one-off slot."
            }
          ]
        },
        {
          "text": "When a user tries to book an overlapping time for the same room, the booking is refused.",
          "origin": "source",
          "citations": [
            {
              "block_id": "B15",
              "quote": "The booking service will reject an overlapping booking for the same room."
            }
          ]
        },
        {
          "text": "When a booking request exceeds three hours in duration, the booking is refused.",
          "origin": "source",
          "citations": [
            {
              "block_id": "A1",
              "quote": "Three hours is the maximum."
            }
          ]
        }
      ],
      "assumptions": [],
      "open_questions": [],
      "covers": [
        "T3",
        "T4",
        "T7",
        "T13"
      ]
    },
    {
      "ref": "S3",
      "kind": "story",
      "parent_ref": "E1",
      "title": "Cancel bookings",
      "description": "As a user, I want to cancel my room booking, so that the room can be freed up for others.\n\nUsers need a way to manage their reservations and release rooms when they are no longer needed.",
      "criteria": [
        {
          "text": "When a user cancels a booking at least one hour before the start time, the cancellation is successful.",
          "origin": "source",
          "citations": [
            {
              "block_id": "A2",
              "quote": "Users can cancel up to one hour before the start."
            }
          ]
        },
        {
          "text": "When a user attempts to cancel a booking less than one hour before the start time, the cancellation counts as a no-show.",
          "origin": "source",
          "citations": [
            {
              "block_id": "A2",
              "quote": "Cancelling later counts as a no-show."
            }
          ]
        }
      ],
      "assumptions": [],
      "open_questions": [],
      "covers": [
        "T15"
      ]
    },
    {
      "ref": "E2",
      "kind": "epic",
      "parent_ref": null,
      "title": "Facilities Administration and Management",
      "description": "Empowers the Facilities Office with administrative controls to block rooms for maintenance, view all booking details including participant identities, and maintain oversight. This delivers operational control and visibility over the library study rooms.",
      "criteria": [
        {
          "text": "When the Facilities Office blocks a room, it becomes unavailable for booking.",
          "origin": "source",
          "citations": [
            {
              "block_id": "B8",
              "quote": "- The Facilities Office can block a room for maintenance."
            }
          ]
        },
        {
          "text": "When the Facilities Office views bookings, they can see who booked each room while students see only that a room is taken.",
          "origin": "source",
          "citations": [
            {
              "block_id": "B26",
              "quote": "Also, my office needs to see who booked each room. Students should only see that a room is taken, not who took it."
            }
          ]
        }
      ],
      "assumptions": [],
      "open_questions": [],
      "covers": []
    },
    {
      "ref": "S4",
      "kind": "story",
      "parent_ref": "E2",
      "title": "Block rooms for maintenance",
      "description": "As a facility administrator, I want to block a room for maintenance, so that users cannot book it while repairs or upkeep are performed.\n\nAdministrators need to take rooms out of service temporarily.",
      "criteria": [
        {
          "text": "When the Facilities Office selects a room to block for maintenance, the room status updates to blocked.",
          "origin": "source",
          "citations": [
            {
              "block_id": "B8",
              "quote": "- The Facilities Office can block a room for maintenance."
            }
          ]
        },
        {
          "text": "When a user tries to book a maintenance-blocked room, the booking is refused.",
          "origin": "proposed",
          "citations": []
        }
      ],
      "assumptions": [],
      "open_questions": [],
      "covers": [
        "T8"
      ]
    },
    {
      "ref": "S5",
      "kind": "story",
      "parent_ref": "E2",
      "title": "View all bookings and details",
      "description": "As a facility administrator, I want a single view of all bookings including booker details, so that the Facilities Office can monitor room usage.\n\nAdministrators need comprehensive visibility while preserving student privacy regarding user identities.",
      "criteria": [
        {
          "text": "When the Facilities Office accesses the booking view, all system bookings are displayed with booker identities.",
          "origin": "source",
          "citations": [
            {
              "block_id": "B6",
              "quote": "- Give the Facilities Office a single view of all bookings."
            },
            {
              "block_id": "B26",
              "quote": "Also, my office needs to see who booked each room."
            }
          ]
        },
        {
          "text": "When a student views room availability, they see that a room is taken without seeing who took it.",
          "origin": "source",
          "citations": [
            {
              "block_id": "B26",
              "quote": "Students should only see that a room is taken, not who took it."
            }
          ]
        }
      ],
      "assumptions": [],
      "open_questions": [],
      "covers": [
        "T5",
        "T16"
      ]
    }
  ],
  "questions": [
    {
      "subject": "Calendar synchronization",
      "question": "Should calendar synchronization (such as syncing bookings to Outlook calendars) be included in the first release, or is it excluded?",
      "why_it_matters": "It determines whether calendar sync development effort is part of the initial scope.",
      "citations": [
        {
          "block_id": "U1",
          "quote": "The reviewer has not answered this yet: Should calendar synchronization (such as syncing bookings to Outlook calendars) be included in the first release, or is it excluded?"
        }
      ],
      "affects": []
    },
    {
      "subject": "Calendar synchronization",
      "question": "Should calendar synchronization (such as syncing bookings to Outlook calendars) be included in the first release, or is it excluded?",
      "why_it_matters": "It determines whether calendar sync development effort is part of the initial scope.",
      "citations": [
        {
          "block_id": "U2",
          "quote": "The reviewer has not answered this yet: Should calendar synchronization (such as syncing bookings to Outlook calendars) be included in the first release, or is it excluded?"
        }
      ],
      "affects": []
    }
  ],
  "people": [
    {
      "ref": "P1",
      "name": "Alex Kim",
      "role": "Product owner",
      "said": "Alex agreed on project scope and that recurring reservations and calendar sync are out of scope for release one.",
      "citations": [
        {
          "block_id": "B13",
          "quote": "Thanks for coming. Today we agree what goes into the first release of room booking."
        },
        {
          "block_id": "B19",
          "quote": "Agreed. Recurring reservations are out of scope for release one."
        },
        {
          "block_id": "B22",
          "quote": "Possibly, but let's not commit to that today."
        },
        {
          "block_id": "B25",
          "quote": "Okay, cancellation and no-shows stay open until Dana confirms."
        }
      ],
      "rights": "not_stated",
      "rights_citations": [],
      "speaker": "SP1"
    },
    {
      "ref": "P2",
      "name": "Dana Ruiz",
      "role": "Sponsor",
      "said": "Dana emphasized ending double bookings, limiting single booking length to three hours, excluding recurring bookings, and ensuring booker visibility for the facilities office.",
      "citations": [
        {
          "block_id": "B14",
          "quote": "The main thing for us is ending double bookings. If two people can take the same room at the same time, we have failed."
        },
        {
          "block_id": "B18",
          "quote": "Not in the first release. Recurring bookings make the clash rules much harder, so let's leave recurring bookings out for now and revisit after launch."
        },
        {
          "block_id": "B20",
          "quote": "One more thing on length. The brief says four hours, but three hours is the most I want for a single booking, or rooms get hogged."
        },
        {
          "block_id": "B24",
          "quote": "We need a rule for no-shows, and for how late someone can cancel, but I have to check with Student Services first."
        },
        {
          "block_id": "B26",
          "quote": "Also, my office needs to see who booked each room. Students should only see that a room is taken, not who took it."
        }
      ],
      "rights": "not_stated",
      "rights_citations": [],
      "speaker": "SP2"
    },
    {
      "ref": "P3",
      "name": "Priya Nair",
      "role": "Developer",
      "said": "Priya noted that rejecting overlapping bookings is straightforward and suggested syncing bookings to Outlook calendars.",
      "citations": [
        {
          "block_id": "B15",
          "quote": "The booking service will reject an overlapping booking for the same room. That part is straightforward."
        },
        {
          "block_id": "B21",
          "quote": "Maybe we could also sync bookings to people's Outlook calendars? It might be nice."
        }
      ],
      "rights": "not_stated",
      "rights_citations": [],
      "speaker": "SP3"
    },
    {
      "ref": "P4",
      "name": "Sam Okafor",
      "role": "End-user representative",
      "said": "Sam highlighted students' desire for single study sessions before exams, asked about recurring bookings for societies, and raised the issue of no-shows.",
      "citations": [
        {
          "block_id": "B16",
          "quote": "Students mostly want a room for a single study session, usually a couple of hours before an exam."
        },
        {
          "block_id": "B17",
          "quote": "Could societies book the same room every week, say every Tuesday evening?"
        },
        {
          "block_id": "B23",
          "quote": "What happens if a student books a room and doesn't turn up? Some rooms sit empty all afternoon."
        }
      ],
      "rights": "not_stated",
      "rights_citations": [],
      "speaker": "SP4"
    }
  ]
}

